    edges = {
        'left': _segments([g[r][0] for r in range(h)], bg),
        'right': _segments([g[r][w - 1] for r in range(h)], bg),
        'top': _segments(g[0], bg),
        'bottom': _segments(g[h - 1], bg),
    }
    opposite = {'left': 'right', 'right': 'left', 'top': 'bottom', 'bottom': 'top'}
    sides = ('left', 'right', 'top', 'bottom')

    markers = [(r, c, g[r][c]) for r in range(1, h - 1) for c in range(1, w - 1)
